#!/usr/bin/env node

import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { build } from "esbuild";

const projectRoot = resolve(import.meta.dirname, "..");
const entry = join(projectRoot, "scripts", "entries", "tour-sentry-entry.js");
const output = join(
  projectRoot,
  "web-tour",
  "js",
  "generated",
  "sentry-browser-10.71.0.min.js",
);
const monitorEntry = join(projectRoot, "web-tour", "js", "tour-monitoring.js");
const monitorOutput = join(
  projectRoot,
  "web-tour",
  "js",
  "generated",
  "tour-monitoring.min.js",
);

await mkdir(dirname(output), { recursive: true });
await build({
  entryPoints: [entry],
  outfile: output,
  bundle: true,
  format: "iife",
  platform: "browser",
  target: ["safari15", "chrome96", "firefox91"],
  minify: true,
  sourcemap: false,
  legalComments: "none",
  treeShaking: true,
});

const generated = await readFile(output, "utf8");
if (!generated.includes("__rainDigitSentrySdk")) {
  throw new Error("Generated tour monitoring bundle does not expose the Sentry adapter.");
}
await writeFile(
  output,
  `/*! @sentry/browser 10.71.0; generated by scripts/generate-tour-monitoring-bundle.mjs */\n${generated}`,
  "utf8",
);
await build({
  entryPoints: [monitorEntry],
  outfile: monitorOutput,
  bundle: false,
  format: "iife",
  platform: "browser",
  target: ["safari15", "chrome96", "firefox91"],
  minify: true,
  sourcemap: false,
  legalComments: "none",
});
console.log(`${output}\n${monitorOutput}`);
